insert into cases (case_id,domain,kind,tech,institution,claimed,claimed_wording,outcome,blocking_evidence,gate_organiser,duration_years,evidence_level,prewarning,maps_to_mode,maps_to_dim,clears_gap,source_url,published_at,retrieved_at,quote,verification_status,note) values ('HC-02','跨校对照','进行时未闭合','“先使用后付费”区域定向专利许可（企业零门槛试用高校专利，试用后再付费）','齐鲁工业大学（山东省科学院）×济南市市场监督管理局（知识产权局）；企业侧示例：荷净（山东）净化科技有限公司','企业与齐鲁工大签订 5 项专利“先用后付”协议、免费试用；成果经二次开发、产品实现批量生产后，预计生产成本降低 40%~50%、一年节省 2,000 多万元','计划','已落地的是“许可协议签署＋免费试用”这一级；成本降幅与节省金额均为“预计”。派发包所称“45 天批量投产”本轮 4 条检索式均未命中，标 ⚠️ 待回源','批量投产的产量/批次/良率与验收记录；试用期后的付费转化记录；成本降幅的实际核算（当前只有“预计”）','济南市市场监督管理局（知识产权局）与齐鲁工业大学签订区域定向许可试点协议；具体企业验收组织方未披露',NULL,'B','只看得出结构','M7','第1维 需求与客户；第3维 制造与交付','把“转化机制”与“技术成熟度”分开：机制（零门槛试用）能降低成交摩擦，但不产生任何技术证据；本卡是“机制很好、证据仍为零”的样本，支持判据不因交易结构创新而升阶段','http://news.cyol.com/gb/articles/2025-06/10/content_mOw3XouVvx.html','2025-06-10','2026-10-27','签订了5项专利“先用后付”协议，可免费试用高校专利技术成果','人工已核对原文','支撑口径：工人日报 2025-06-10（B 级）；机制规模见 S-927（济南：专利池 69 家/1,862 项/转化 3,700 件次/收益 23.8 亿元）与山东省科协 2026-07-20（齐鲁工大累计 2,200 余件次、服务企业 520 余家）——**规模数字口径不同，不得相加**。⚠️“45 天批量投产”无来源，禁止对外引用') on conflict (case_id) do nothing;
insert into cases (case_id,domain,kind,tech,institution,claimed,claimed_wording,outcome,blocking_evidence,gate_organiser,duration_years,evidence_level,prewarning,maps_to_mode,maps_to_dim,clears_gap,source_url,published_at,retrieved_at,quote,verification_status,note) values ('HC-03','跨校对照','进行时未闭合','1.1 类新药益母草碱（SCM-198）专利包：8 项专利（含日本、欧盟同族）＋专有技术与临床前研究资料','复旦大学（朱依谆团队）→ 珠海横琴新区中珠正泰医疗管理有限公司（中珠医疗全资子公司）','转让合同总额 1.5 亿元，其中前期技术转让费（8 项专利转让）1,800 万元、后续开发里程碑付款 13,200 万元；无形资产评估价 2,400 万元（银信评报字(2016)沪第1291号，基准日 2016-10-31）','已完成','2016-12-01 签约并进入专利权人变更程序；技术本身仍处临床前（T2），后续以里程碑分期支付；未检索到临床批件与任何 T3/T4 级验证','临床批件与 Ⅰ/Ⅱ/Ⅲ 期数据（技术侧证据）；里程碑是否兑现的后续公告；派发包所称“评估价 217 万 vs 挂牌 1.5 亿”这一组数字的回源（本轮 4 条检索式未命中 ⚠️）','银信资产评估有限公司（评估）；国家药监部门（后续临床批件，未见）','8.0','B','能提前看出','M5','第4维 权属与合规','把“成交金额”与“技术成熟度”彻底分开：8 项已授权专利＋1.5 亿元合同，技术仍停在临床前 T2——专利与合同都不是跃迁门票；同时给出**同一包专利的两种口径**（2,400 万评估价 vs 1.5 亿合同总额，其中 1.32 亿是里程碑），是“禁止把合同金额当到账收入”的实物样本','http://static.cninfo.com.cn/finalpage/2016-12-15/1202875407.PDF','2016-12-15','2026-10-27','评估对象的评估价值为2400万元','人工已核对原文','口径警示：①1.5 亿是**合同总额**（含 1.32 亿里程碑），不是到账收入，可比的最近口径是前期专利转让费 1,800 万；②派发包所称“评估价 217 万”本轮未回源，本卡一律不采用，标 ⚠️ 待回源；③交易签约方为中珠医疗/中珠正泰，公告口径与媒体报道（S-925，C 级）并存，取数用公告') on conflict (case_id) do nothing;
insert into cases (case_id,domain,kind,tech,institution,claimed,claimed_wording,outcome,blocking_evidence,gate_organiser,duration_years,evidence_level,prewarning,maps_to_mode,maps_to_dim,clears_gap,source_url,published_at,retrieved_at,quote,verification_status,note) values ('A03','领域A 气体传感','成功跃迁','NDIR 红外气体传感器／沼气分析仪','武汉四方光电（创始人熊友辉，华科煤燃烧国家重点实验室出身）','2003 年创办，2006 年中标农业部沼气服务体系工程约 10 万套分析仪配套','已完成','2021-02-09 科创板上市（688665），2024 产值 8.73 亿；此后获 UL、Ex 防爆、IATF16949','缺第一个规模化示范工程订单（没有 10 万套就没有后续运行履历）','农业部沼气服务体系工程项目','7.0','B','能提前看出','M3','第6维 准入与合规','支撑「跃迁门票是第三方现场验收而非论文专利」；给时长异常检测提供 4-7 年样本','https://m.antpedia.com/ibook/news/608921.html','2025-07-11','2026-10-24','需要大约10万套沼气分析仪；销售额突破5000万','人工已核对原文','示例行；源自 05_案例库 C3') on conflict (case_id) do nothing;
insert into cases (case_id,domain,kind,tech,institution,claimed,claimed_wording,outcome,blocking_evidence,gate_organiser,duration_years,evidence_level,prewarning,maps_to_mode,maps_to_dim,clears_gap,source_url,published_at,retrieved_at,quote,verification_status,note) values ('HC-01','领域A 气体传感','进行时未闭合','嗅辨（气体检测）装备：检测汽车内饰件“异味”，报道称为“能像人类鼻子一样”的新型嗅辨装备','宁波中科新材概念验证中心（在孵项目；研发团队与完成单位名称报道未披露）','该技术进入宁波中科新材概念验证中心项目库后，得到权威专家认定并获得多项支持，产业化进程正加速推进','来源声称待核验','仅到“进入概念验证中心项目库＋专家认定”一级：报道未给认定组织方名单、认定结论、检测性能值、样机数量与任何客户试用记录','第三方现场验收（组织方＋连续运行时长）；检出限/重复性/交叉干扰等可比对性能值；车厂或内饰件厂的采用记录与批次数据','宁波中科新材概念验证中心（专家认定的组织方；名单与认定结论原文未取得 ⚠️）',NULL,'B','能提前看出','M3','第6维 准入与合规；第2维 性能与替代；第3维 制造与交付','给“概念验证中心通过＝已可实现产业化”这一常见误读提供反例：验证券只有“权威专家认定”字样，没有性能值与现场验收，按判据最高只能支撑 T2；同时证明概念验证平台本身不签发任何准入类证书','http://cpc.people.com.cn/n1/2025/1120/c461139-40608076.html','2025-11-20','2026-10-27','去年，该技术进入宁波中科新材概念验证中心的项目库后，得到权威专家认定并获得多项支持','人工已核对原文','新华社 2025-11-20 稿（B 级）为单一来源，未见宁波方或企业方公告；同一段还给出“经中试验证产业化成功率 80% vs 未经 30%”的统计口径，未注出处，**不得对外引用**') on conflict (case_id) do nothing;
