insert into cases (case_id,domain,kind,tech,institution,claimed,claimed_wording,outcome,blocking_evidence,gate_organiser,duration_years,evidence_level,prewarning,maps_to_mode,maps_to_dim,clears_gap,source_url,published_at,retrieved_at,quote,verification_status,note) values ('LJQ-C1','领域B 能源环保','成功跃迁','甲醇制低碳烯烃（DMTO／DMTO-Ⅱ／DMTO-Ⅲ）','中国科学院大连化学物理研究所＋中国石化＋神华集团','2006 年完成万吨级工业性试验并通过技术成果鉴定；2010-08-08 60 万吨/年示范投料；2011-03-23 至 26 通过 72 小时性能考核','已完成','逐级放大且每级都有验收：千吨级中试、万吨级工业性试验（近 1,200 小时三阶段）、60 万吨/年工业示范（72 小时性能考核）、第二代 2010-06-26 鉴定、第三代 2020-09-26 现场 72 小时连续运行考核与 2020-11-09 科技成果鉴定','缺每级都有第三方现场考核的正样本（本轮已补齐两级：鉴定与 72 小时考核）','中国石油和化学工业联合会（及其前身中国石化协会）','4.6','B','能提前看出','M1','第6维 准入与合规（三层）；第2维 性能与替代','为「逐级放大＋每级验收」范式与「时长异常检测」提供 2006 至 2011 的 5 年样本；验收组织方与连续运行时长两项均已落到逐字原文','https://70.dicp.ac.cn/info/1006/1847.htm','2012-03-13','2026-10-27','2011年3月23日到3月26日，进行了72小时性能考核','人工已核对原文','半包行。原件级证据（鉴定证书、考核报告）未取到，本轮只到单位官网所史与媒体报道两级；DMTO-Ⅱ 与 Ⅲ 的指标为鉴定报告值，非第三方复检') on conflict (case_id) do nothing;
insert into cases (case_id,domain,kind,tech,institution,claimed,claimed_wording,outcome,blocking_evidence,gate_organiser,duration_years,evidence_level,prewarning,maps_to_mode,maps_to_dim,clears_gap,source_url,published_at,retrieved_at,quote,verification_status,note) values ('LJQ-C3','领域B 能源环保','成功跃迁','15 万吨/年燃烧后 CO2 捕集与封存示范（国能锦界）','国家能源集团国电电力锦界能源有限责任公司','2021-06-25 通过 168 小时试运行投入生产运营；2023 年 3 月通过国家科技部课题验收；报告吸收剂再生热耗小于 2.35 GJ/tCO2','已完成','两级：168 小时试运行（投运）与国家重点研发计划课题验收（2023-03）；捕集规模 15 万吨/年','缺验收证书原件与投运阶段的性能考核组织方；捕集量与纯度未按运行小时粒度披露','国家科技部（课题验收方）；试运行考核组织方未在报道中逐字出现','1.6','C','能提前看出','M2','第6维 准入与合规；第2维 性能与替代','补验收文件长什么样样本的第二级：课题验收不等于性能考核，二者要分列；同时给出能耗指标原文位置','https://www.cpnn.com.cn/qiye/jishu2023/202408/t20240813_1727563_wap.html','2024-08-14','2026-10-27','2023年3月，CCUS项目顺利通过国家科技部课题验收','人工已核对原文','半包行。仅到媒体报道级（C 级），验收证书未取到；另有一条中国环境监测总站第三方评测的说法（新华信用，摘要级）待回源，若成立可升 A 级类型') on conflict (case_id) do nothing;
insert into cases (case_id,domain,kind,tech,institution,claimed,claimed_wording,outcome,blocking_evidence,gate_organiser,duration_years,evidence_level,prewarning,maps_to_mode,maps_to_dim,clears_gap,source_url,published_at,retrieved_at,quote,verification_status,note) values ('LJQ-C4','领域B 能源环保','成功跃迁','陆上石油天然气工业甲烷排放监测技术（GB/T 48149—2026 及配套装备）','市场监管总局（国家标准委）归口；起草与验证涉及中国环境监测总站、国家管网集团科学技术研究总院等','该标准已在中国石油、中国石化、国家管网集团等多家央企完成验证应用','已完成','标准发布加央企验证应用两级；未取到验证方案、覆盖量程与逐装置清单','缺第三方性能检测报告与逐装置验证记录；标准正文与实施日未取到','国家标准委（标准发布）；验证应用的组织方与报告未逐字披露',NULL,'B','只看得出结构','M2','第6维 准入与合规（第③层 标准与定期检定）','本领域第③层的实物样本：既不是检测报告也不是企业自述，而是方法标准加央企验证这一混合形态，说明第③层在本领域承担原领域定期检定的功能','https://www.sac.gov.cn/xw/bzhdt/art/2026/art_8df84f3d7fcb4ad7afdc1cb910a7f83a.html','2026-08-31','2026-10-27','该标准已在中国石油、中国石化、国家管网集团等多家央企完成验证应用','人工已核对原文','半包行。标准发布日 2026-08-28 未逐字核实故不写入 published_at；实施日待回标准著录页') on conflict (case_id) do nothing;
insert into cases (case_id,domain,kind,tech,institution,claimed,claimed_wording,outcome,blocking_evidence,gate_organiser,duration_years,evidence_level,prewarning,maps_to_mode,maps_to_dim,clears_gap,source_url,published_at,retrieved_at,quote,verification_status,note) values ('LJQ-F1','领域B 能源环保','监管处置','园区级准入：氢能产业配套制氢专用区域的化工园区功能定位','云浮市人民政府（佛山（云浮）产业转移工业园）','该专用区域曾作为电解水制氢项目的落地载体（区域功能定位）','已完成','2022-10-07 公告取消该区域的化工园区功能定位，并严禁原有危化企业超出规划红线新建、扩建','化工园区资格与安全条件审查（第①层强制准入），不是性能问题也不是资金问题','云浮市人民政府（依据粤安办函〔2022〕45号等省级整治要求）',NULL,'B','能提前看出','M4','第6维 准入与合规（第①层）','给缺安评或园区资格而无法投运这一卡点补上中国侧官方文件（此前只有说法没有文件），同时证明本领域第①层的载体是区域资格而非产品证书','https://www.yunfu.gov.cn/zwgk/tzgg/content/post_1632245.html','2022-10-07','2026-10-27','关于取消佛山（云浮）产业转移工业园氢能产业配套制氢专用区域化工园区功能定位的公告','人工已核对原文','半包行。区域内存续项目清单与个案处理结果未公开（公告允许在建未投产项目继续），是否作为独立案例深挖请队长定') on conflict (case_id) do nothing;
insert into cases (case_id,domain,kind,tech,institution,claimed,claimed_wording,outcome,blocking_evidence,gate_organiser,duration_years,evidence_level,prewarning,maps_to_mode,maps_to_dim,clears_gap,source_url,published_at,retrieved_at,quote,verification_status,note) values ('LJQ-F2','领域B 能源环保','进行时未闭合','氢燃料电池公交车队（示范运营与购置补贴）','佛山市公交企业／佛山市交通运输局','2018 至 2020 年购置 989 台氢能公交车开展示范运营，购置补贴 50 万元/辆','已完成','2021 年至今 5 年零新购；运营方称加氢价格较高抬高使用成本；车辆仍在 5 区 37 条公交线路，但当前在运数量官方从未给出','长期在运数量与氢价（外生变量）；缺最基础的运行统计指标','佛山市交通运输局（两次书面回应，经媒体转述，原件未取到）','5.0','C','能提前看出','M3','第1维 需求与客户；第6维 准入与合规','确认既有案例条目「缺在运数量」这一说法成立，并给出两句可引用的原文；同时说明所谓大半闲置为舆论口径，不得引用','https://www.thepaper.cn/newsDetail_forward_32079547','2025-12-02','2026-10-27','2018年至2020年期间，佛山市先后购置了989台氢能公交车开展示范运营','人工已核对原文','半包行。交通局答复书原件未取到，须走政府门户或信息公开申请；因此本卡只到 C 级') on conflict (case_id) do nothing;
