insert into cases (case_id,domain,kind,tech,institution,claimed,claimed_wording,outcome,blocking_evidence,gate_organiser,duration_years,evidence_level,prewarning,maps_to_mode,maps_to_dim,clears_gap,source_url,published_at,retrieved_at,quote,verification_status,note) values ('MX-C1','领域C 医疗传感','成功跃迁','冠状动脉钙化 AI 自动检测算法（从常规 CT 扫描）','Stanford AIMI Center（Curtis Langlotz 团队）+ 跨学科团队（心内科、放射科、计算机科学）','从常规 CT 扫描自动检测冠状动脉钙化过量（无需额外冠脉扫描）；RCT 验证：干预组他汀使用率 >50% vs 对照组 7%','已完成','算法已授权 startup；通过 FDA clearance 流程；正在向全美医院销售；Langlotz 称''could save tens or hundreds of thousands of lives''','FDA clearance（具体 K 编号未在访谈中给出 ⚠️）；RCT 验证（具体试验注册號与样本量未在访谈中给出 ⚠️）；Stanford OTL 许可记录（访谈提及''licensed to a startup''但未给公司名 ⚠️）','FDA + Stanford OTL',NULL,'B','能提前看出','M2','第6维 准入与合规','OTL 授权后受让方完成注册并上市（满足配额①）：Stanford Report 访谈明确写''licensed to a startup, gone through the FDA clearance process, now being sold to hospitals across the country''；为第 6 维提供''强制准入＝FDA clearance''的正面案例；RCT 验证（干预组 >50% vs 对照组 7%）是''第三方现场验收''在医疗 AI 领域的等价物','https://news.stanford.edu/stories/2025/11/research-matters-curtis-langlotz','2025-11-19','2026-10-27','licensed to a startup...gone through the FDA clearance process','部分核（仅著录）','Stanford Report 官方报道（B级）但为 Langlotz 自述访谈，未给 startup 名称、FDA K 编号、RCT 注册號与样本量。duration_years 留空（未知，访谈未给研发起始年）。⚠️ 需补：① FDA 510(k) 数据库按产品代码或申请人检索 ② Stanford OTL TechFinder 许可记录 ③ ClinicalTrials.gov RCT 注册信息。本卡可回源性受限于访谈自述，若补不到 FDA 编号则 verification_status 维持''部分核（仅著录）''。') on conflict (case_id) do nothing;
insert into cases (case_id,domain,kind,tech,institution,claimed,claimed_wording,outcome,blocking_evidence,gate_organiser,duration_years,evidence_level,prewarning,maps_to_mode,maps_to_dim,clears_gap,source_url,published_at,retrieved_at,quote,verification_status,note) values ('MX-C2','领域C 医疗传感','成功跃迁','AI 自主诊断系统（视网膜影像深度学习，IDx-DR / LumineticsCore）','University of Iowa（Michael Abramoff 团队）→ IDx Technologies → Digital Diagnostics','首个获 FDA 授权上市、无需临床医生判读即可自动检测糖尿病视网膜病变的 AI 设备；关键试验 900 人 10 站点','已完成','2018-01-12 FDA De Novo 分类授权（DEN180001）；新建产品分类 21 CFR 886.1100；2018-04-11 FDA 官方宣布；产品后更名 LumineticsCore；配合 Topcon NW400 视网膜相机；适应症：≥22 岁已确诊糖尿病未诊断过 DR 的成人','FDA De Novo 分类授权（DEN180001）；关键性临床试验（900 人、10 初级保健站点、多中心前瞻性）；npj Digital Medicine 发表','FDA（美国食品药品监督管理局）','6.0','B','能提前看出','M2','第6维 准入与合规','先拿认证后谈性能（满足配额②）：FDA De Novo 授权在前（2018-01），临床数据公开发表在后；为第 6 维提供「强制准入＝注册证/上市许可」的 FDA 正面案例；证明 AI 诊断设备的准入路径是 De Novo（无先例产品时新建分类），与气体传感的 CPA 型式批准（有先例时走 510(k) 类比）形成制度对照','https://www.fda.gov/news-events/press-announcements/fda-permits-marketing-artificial-intelligence-device-detection-certain-diabetic-retinopathy','2018-04-11','2026-10-27','first device authorized for marketing that doesn''t require a clinician','人工已核对原文','FDA 官方新闻稿全文已读（B级）；De Novo 编号 DEN180001、21 CFR 886.1100、产品代码 PIB 均来自 FDA 新闻稿与 Brainwave Post 综述交叉核对。关键试验灵敏度 87.2%/特异度 90.7% 来自二手综述（Q-MX-C2-02 outcome=未检索到 npj Digital Medicine 原文），在 E-MX-C2-02 标 ⚠️ 仅著录。duration_years=6.0 按 2012 年 Abramoff 团队开始研发至 2018 年 FDA 授权计（推定，需核 ⚠️）。IDx 后被 Digital Diagnostics 收购，产品更名 LumineticsCore。') on conflict (case_id) do nothing;
