insert into cases (case_id,domain,kind,tech,institution,claimed,claimed_wording,outcome,blocking_evidence,gate_organiser,duration_years,evidence_level,prewarning,maps_to_mode,maps_to_dim,clears_gap,source_url,published_at,retrieved_at,quote,verification_status,note) values ('MX-C4','领域C 医疗传感','成功跃迁','腕带式特发性震颤治疗设备（外设神经刺激）','MIT（起源于 2.009 产品设计课）→ Encora Therapeutics（MIT 校友创办）','9 年从课堂项目到 FDA clearance；治疗成人特发性震颤（essential tremor）','已完成','FDA clearance 已获（MIT News 2026-10-02 报道）；MIT TLO 参与许可；具体 K 编号与 clearance 日期需补查 FDA 数据库 ⚠️','FDA 510(k) clearance（推定 Class II 外设神经刺激器；具体产品代码与 K 编号待核 ⚠️）；CE Mark 状态未确认；ISO 13485 证书未公开','FDA + MIT TLO','9.0','B','能提前看出','M2','第6维 准入与合规','跨校池可回源许可记录（满足配额③）：MIT News 报道明确写 MIT spinout + FDA cleared；9 年时长落在案例库 T2→T4 经验时长 3-15 年区间内，为时长异常检测判据提供医疗侧样本；''课堂项目→创业公司→FDA clearance''路径是 MIT TLO 最典型的早期成果转化模式','https://news.mit.edu/2026/mit-class-project-fda-cleared-treatment-tremors-1002','2026-10-02','2026-10-27','nine years later the FDA has cleared Encora''s device','部分核（仅著录）','MIT News 报道 URL 为推定（基于标题与日期，MIT 首页 Spotlight 摘要确认内容存在）⚠️ 需补核具体 URL。FDA K 编号与 clearance 日期需补查 openFDA 510(k) 数据库。duration_years=9.0 按 MIT News ''nine years later'' 计。本卡同时作为 GS-12 跨校对照席的立项基础（MX-P4）。') on conflict (case_id) do nothing;
insert into cases (case_id,domain,kind,tech,institution,claimed,claimed_wording,outcome,blocking_evidence,gate_organiser,duration_years,evidence_level,prewarning,maps_to_mode,maps_to_dim,clears_gap,source_url,published_at,retrieved_at,quote,verification_status,note) values ('MX-C5','领域C 医疗传感','进行时未闭合','六自由度电容式力/扭矩传感器（MEMS 触觉传感）','Stanford University · Biomimetics and Dexterous Manipulation Lab（Mark Cutkosky 团队）；发明人 Xin Alice Wu, John Ulmen, Mark Cutkosky','US Patent 10,267,690 已授权；原型对标商用 ATI Gamma Load Cell 测试通过；Stanford OTL 正在营销许可','已完成','Stanford OTL TechFinder 页面（Docket S16-273）显示技术处于''Prototype''阶段并正在营销许可（Licensing Contact: Matthew Ryan）；截至 2026-10-27 未检索到独占许可受让方公开信息（Q-MX-C5-02 outcome=未检索到）；USPTO 专利转让记录无转让登记','独占许可受让方确认（TechFinder 未披露）；医疗应用场景的 FDA 510(k) 路径（若用于手术机器人力反馈则需 clearance）；量产工艺验证（从实验室原型到可制造产品）','Stanford OTL（许可方）',NULL,'B','只看得出结构','M2','第6维 准入与合规','传感器硬件（非 AI 软件）与气体传感 MEMS 器件路线最接近——同为''物理量→电信号→算法反演''机制；Stanford OTL 许可模式（Bayh-Dole 联邦资助→大学持有→独占许可给 startup）与气体传感''院所持有→许可给企业''的中国模式形成制度对照；kind 填''进行时未闭合''因受让方未确认——若后续查到许可记录可升级为''成功跃迁''','https://techfinder.stanford.edu/technology/small-robust-highly-sensitive-six-degree-freedom-capacitive-forcetorque-sensor','2026-08-05','2026-10-27','U.S. Patent No. 10,267,690...Licensing Contact Matthew Ryan','人工已核对原文','Stanford OTL TechFinder 官方页（B级）全文已读。duration_years 留空（未知：专利授权日 2019-04-23 至 TechFinder 页面更新 2026-08-05 约 7 年，但不确定研发起始年）。prewarning 填''只看得出结构''——从 TechFinder 页面能看出技术成熟度（原型已对标商用设备）与许可路径（OTL 营销中），但看不出商业结果（无受让方=无后续运行履历）。⚠️ 需补：① USPTO assignment 记录 ② Stanford OTL 年报中 S16-273 许可状态 ③ 若有受让方则查其 FDA/CE 注册状态。') on conflict (case_id) do nothing;
insert into cases (case_id,domain,kind,tech,institution,claimed,claimed_wording,outcome,blocking_evidence,gate_organiser,duration_years,evidence_level,prewarning,maps_to_mode,maps_to_dim,clears_gap,source_url,published_at,retrieved_at,quote,verification_status,note) values ('MX-F1','领域C 医疗传感','终止于T3','AI 临床决策支持系统（NLP + 机器学习，Watson for Oncology）','IBM Watson Health / Memorial Sloan Kettering Cancer Center (MSKCC)','与 MSKCC 顶级专家的治疗建议一致性达 90% 以上（iKang/BAHEAL/IBM 2017-07-28 联合新闻稿）','来源声称待核验','2019 年青岛大学附属医院 362 例回顾性研究显示卵巢癌一致性 96%、胃癌仅 12%（Zhou et al. Oncologist 2019）；2017 年 STAT News 披露 IBM 内部文件承认系统用合成病例训练、出现''unsafe and incorrect''建议；MD Anderson 终止白血病项目（已支出约 6200 万美元）；2022-01-21 IBM 将 Watson Health 数据与分析资产出售给 Francisco Partners（彭博估约 10 亿美元）','覆盖代表性人群与量程的多中心前瞻性临床验证；真实患者数据训练而非合成病例；各癌种分项一致性数据而非单一''90%以上''笼统宣称',NULL,'10.0','B','能提前看出','M1','第6维 准入与合规','支撑「精度宣称须由覆盖代表性人群与量程的临床验证支撑，否则封顶 T2」；为第 6 维提供医疗侧「注册证/临床证据」对照；证明合成数据训练不能替代真实世界验证；监管机关（FTC 在 Aura Labs 案中）亲自定义了测量类结论的最低证据等级','https://www.sec.gov/Archives/edgar/data/1524190/000110465917047881/a17-18579_1ex99d1.htm','2017-07-28','2026-10-27','reached 90% or above concordance','人工已核对原文','90% 宣称出自 iKang/BAHEAL/IBM 联合新闻稿（SEC EDGAR 6-K 附件）；Zhou et al. Oncologist 2019（DOI 10.1634/theoncologist.2018-0255）提供反证；STAT News 2018-07-25 与 2017-09-05 两篇调查报道披露内部文件；IBM 2022-01-21 官方公告出售。MSKCC 是否正式终止合作未检索到明确公告（Q-MX-F1-05 outcome=未检索到）。''约 20 位医生标注合成病例''这一具体数字未在公开来源中直接确认，工单原文表述待核 ⚠️。duration_years=10.0 按 2012 年 IBM-MSKCC 合作宣布至 2022 年资产出售计。') on conflict (case_id) do nothing;
insert into cases (case_id,domain,kind,tech,institution,claimed,claimed_wording,outcome,blocking_evidence,gate_organiser,duration_years,evidence_level,prewarning,maps_to_mode,maps_to_dim,clears_gap,source_url,published_at,retrieved_at,quote,verification_status,note) values ('MX-F2','领域C 医疗传感','监管处置','智能手机 App 血压测量（宣称可替代袖带）','Aura Labs, Inc.（dba AuraLife / AuraWare），创始人 Ryan Archdeacon（美国）','宣称准确度与传统袖带相当、可替代袖带（App Store 与 Google Play 营销文案）','来源声称待核验','FTC 认定 App 测量值与袖带存在''clinically and statistically significant deviations''；和解令（2016-12-12，美国加州中区联邦法院）禁止今后无证据支撑的健康宣称；判决 $595,945.27（因无力支付暂缓）；App 2014-06 至 2015-06 收入 >$600,000；创始人五星自推未披露关联','覆盖实际工况与代表性人群的人体临床测试（FTC 和解令原文定义：human clinical testing...conform to actual use conditions, include a representative range of blood pressures and representative groups of subjects）','FTC（美国联邦贸易委员会）+ 美国加州中区联邦地区法院','2.0','A','能提前看出','M3','第6维 准入与合规','监管机关亲自定义「测量类结论的最低证据等级」——支撑 T3/T4 必须 A 级（第三方检测或核验记录）；为第 6 维提供医疗侧「强制准入＝注册证或上市许可」的 FTC 执法对照；证明''论文说得很满、监管不认''在消费级健康 App 同样成立','https://www.ftc.gov/news-events/news/press-releases/2016/12/marketers-blood-pressure-app-settle-ftc-charges-regarding-accuracy-app-readings','2016-12-12','2026-10-27','clinically and statistically significant deviations','人工已核对原文','FTC 官方新闻稿全文已读（A级）；JAMA Internal Medicine Plante 2016 研究为关键临床证据但本轮未取到原文（Q-MX-F2-02 outcome=未检索到），在 E-MX-F2-03 标 ⚠️ 仅著录。duration_years=2.0 按 App 2014-06 上架至 2016-12 FTC 和解计。示例行 cases_示例.csv 已有 C01 骨架（部分核·仅著录），本行升级为人工已核对原文。') on conflict (case_id) do nothing;
insert into cases (case_id,domain,kind,tech,institution,claimed,claimed_wording,outcome,blocking_evidence,gate_organiser,duration_years,evidence_level,prewarning,maps_to_mode,maps_to_dim,clears_gap,source_url,published_at,retrieved_at,quote,verification_status,note) values ('MX-F3','领域C 医疗传感','监管处置','微流控''一滴血''多项目血液检测（Edison 设备 + nanotainer）','Theranos, Inc.（Elizabeth Holmes 创办，2003，美国加州 Palo Alto）','宣称用 proprietary Edison 设备从指尖几滴血完成 200+ 项血液检测；峰值估值 $9B（2014）；Walgreens 门店合作（2013-09 起）','来源声称待核验','CMS 2016-01 检查发现''immediate jeopardy to patient health and safety''；2016-07 吊销 Newark CA 实验室 CLIA 执照 + 禁止 Holmes 2 年内拥有/运营实验室；近 100 万份检测结果被作废/纠正；Walgreens 终止合作；Edison 质控 29% 超出自身标准范围；实际仅用 Edison 完成约 10% 测试；SEC 2018-03 指控欺诈；Holmes 2022-01 被判 4 项投资者欺诈罪成立（135 个月 + $452M 赔偿）；Balwani 2022-07 被判 12 项罪名成立（13 年）；公司 2018-09 解散','独立第三方临床验证（无同行评审论文发表）；FDA 从未正式批准 Edison 设备；CLIA 实验室认证（已被吊销）；质控体系合规','CMS（美国医疗保险和医疗补助服务中心）+ SEC + DOJ','15.0','A','能提前看出','M1','第6维 准入与合规','最极端的''宣称很满、监管不认''案例：没有论文只有专利和宣传；监管（CMS）直接吊销执照；为第 6 维提供''强制准入＝CLIA 实验室认证''的执法对照；证明''缺第三方验证 → 封顶 T2''在医疗检测领域同样成立且后果更严重（刑事追责）。注意：Theranos 偏''证据造假''而非''证据不足''，与工单要求的''精度宣称被临床推翻''有距离——但 CMS 29% 质控超范围是实打实的''精度宣称被监管检查推翻''','https://www.biopharmadive.com/news/federal-inspection-report-reveals-major-problems-at-theranos-lab/416680/','2016-07-08','2026-10-27','29% of quality-control checks on Edison provided results out of range','部分核（仅著录）','CMS 121 页检查报告原文未直接获取（Q-MX-F3-02 outcome=未检索到），关键数字（29% 质控超范围、年 89 万份测试、Edison 仅做约 10%）来自 BioPharma Dive 对报告的报道（C级）。SEC/DOJ 文件为 B级但本轮未直接核原文。duration_years=15.0 按 2003 创办至 2018 解散计。verification_status 填''部分核（仅著录）''因 CMS 报告原文与 SEC/DOJ 判决书均未直接核对。⚠️ 需补：CMS 报告原文（FOIA）、SEC v. Holmes 案判决书、US v. Holmes 刑事判决书。') on conflict (case_id) do nothing;
insert into cases (case_id,domain,kind,tech,institution,claimed,claimed_wording,outcome,blocking_evidence,gate_organiser,duration_years,evidence_level,prewarning,maps_to_mode,maps_to_dim,clears_gap,source_url,published_at,retrieved_at,quote,verification_status,note) values ('MX-F4','领域C 医疗传感','终止于T3','AI 症状检查器 + 远程问诊平台（AI-first primary care）','Babylon Health（2013 伦敦创办；创始人 Ali Parsa）','宣称 AI 可替代全科医生问诊；2021-10 SPAC 上市估值 $4.2B；2022 收入 $1.1B','来源声称待核验','2022 净亏 $221M；2023-08 美国 Chapter 7 清算；UK 业务以 £500K 出售给 eMed Healthcare UK；Rwanda 业务关停；市值从 $4.2B 跌至 $21.7M；核心失败：NHS 单一支付方依赖 + 临床验证被 The Lancet 与 UK 监管机构持续质疑 + NICE 框架下缺乏正面评价','NICE（英国国家卫生与临床优化研究所）数字健康技术评估正面评价；覆盖代表性人群的前瞻性临床验证（The Lancet 批评其验证方法学）；多元化支付方（脱离 NHS 单一依赖）','NICE + UK CQC + 美国 Chapter 7 法院','10.0','C','能提前看出','M4','第6维 准入与合规','依赖单一买家（满足配额④）：NHS 为唯一大规模支付方，政治与财务波动直接致命；为第 6 维提供''市场型认证＝NICE 评价''的负面对照——NICE 未给正面评价 = 无法获得可持续报销路径；与气体传感''依赖单一买家（如国家管网框架）''的失败模式直接对照','https://healthcarediscovery.ai/after-the-bitter-lesson-healthcare-ai/','2026-05-12','2026-10-27','By the autumn of 2023 the company had collapsed','部分核（仅著录）','二手分析（C级）为主；Chapter 7 法院文件与 SEC 原始公告未检索到（Q-MX-F4-02 outcome=未检索到）；$4.2B/$1.1B/$221M/£500K/$21.7M 等数字来自两篇二手分析交叉核对一致但均非原始文件。duration_years=10.0 按 2013 创办至 2023 破产计。⚠️ 需补：PACER 法院文件、SEC EDGAR 20-F/6-K、The Lancet 批评原文、NICE 评估报告。') on conflict (case_id) do nothing;
insert into cases (case_id,domain,kind,tech,institution,claimed,claimed_wording,outcome,blocking_evidence,gate_organiser,duration_years,evidence_level,prewarning,maps_to_mode,maps_to_dim,clears_gap,source_url,published_at,retrieved_at,quote,verification_status,note) values ('MX-F5','领域C 医疗传感','终止于T2','Watson-based 白血病治疗决策支持系统','MD Anderson Cancer Center × IBM Watson Health（2012 合作启动）','IBM 宣称 Watson 可为白血病提供''认知计算''治疗决策支持；MD Anderson 为最大最贵的 Watson Health 合作项目','来源声称待核验','支出约 $62M 后 2016 年项目终止未实现部署；UT System 审计发现项目管理失败与临床性能疑虑；为 Watson Health 最大单笔合作失败','独立第三方临床验证（Watson 建议与肿瘤委员会决策的一致性研究）；EHR 系统集成验证（与 MD Anderson 院内系统对接）；FDA 临床决策支持软件监管路径明确化（2012-2016 期间路径不清）','UT System 审计 + MD Anderson 内部决策','4.0','C','能提前看出','M5','第6维 准入与合规','系统集成对接失败（满足配额③）：$62M 支出后未部署，核心原因是 Watson 无法与 MD Anderson 院内 EHR/工作流集成 + 临床性能未达预期；与气体传感''系统集成对接失败（如与 SCADA/DCS 对接）''直接对照；为第 6 维提供''强制准入＝FDA CDS 监管路径''在 2012-2016 期间不明确的制度性对照','https://www.statnews.com/2017/09/05/watson-ibm-cancer/','2017-09-05','2026-10-27','MD Anderson...ended its Watson-based leukemia project','部分核（仅著录）','STAT News 2017-09-05 为首次披露来源（C级媒体）；$62M 数字经 datafield.dev 与 healthcarediscovery.ai 二手转引交叉核对一致但未经 MD Anderson 或 UT System 官方确认（Q-MX-F5-02 outcome=未检索到审计原文）。duration_years=4.0 按 2012 合作启动至 2016 终止计。⚠️ 需补：UT System 审计报告原文（可能需 FOIA）、MD Anderson 官方声明。') on conflict (case_id) do nothing;
insert into cases_extra (case_id,title,domain,kind,tech,institution,claimed,claimed_wording,outcome,gate,evidence_level,maps_to,blocking,source_url,quote,quote2,published_at,retrieved_at,access_status,verification_status,note,batch,created_at) values ('X-01','中广核大亚湾：国产化发电机气体分析装置投运','领域A 气体传感','工程验证','发电机氢气纯度/多参量气体分析装置（NDIR 类气体分析 + 智能芯片集成）','中国广核集团 大亚湾核电运营管理有限责任公司（联合设备厂家）','D224 大修中完成改造，集团内在运机组首台国产化发电机气体分析装置投入运行；2 号机组气体置换后并网满功率运行，氢气浓度测量满足标准','已完成','已投运并随机组并网运行；测量精度 0.2%','出厂测试阶段由项目组联合维修专业组成验收团队验收；现场实施后随机组并网运行','B','["跃迁门票是第三方现场验收（同类单位验收团队＋随机组运行）", "T4 要素：实际环境运行＋运行结果"]','报道未给出连续运行时长与独立第三方检测报告编号；「精度 0.2%」为报道口径，未附检测方法','https://china-nea.cn/site/content/49468.html','近期，随着D224大修发电机气体分析装置改造项目圆满完成，中国广核集团内在运机组首台国产化发电机气体分析装置成功投入运行','随着大亚湾核电站2号机组发电机气体置换完成、成功并网满功率运行，氢气浓度测量满足标准，气体压力、流量稳定，国产化气体分析装置应用落地取得圆满成功','2025-06-12','2026-10-29','full','人工已核对原文','行业协会会员动态，来源标注「大亚湾核电」。适合演示「验收＋实际运行」与「报道未给时长，T4 要素不全」的差别。','2026-10-29-全网检索','2026-10-29T02:06:12') on conflict (case_id) do nothing;
insert into cases_extra (case_id,title,domain,kind,tech,institution,claimed,claimed_wording,outcome,gate,evidence_level,maps_to,blocking,source_url,quote,quote2,published_at,retrieved_at,access_status,verification_status,note,batch,created_at) values ('X-02','苏州芯镁信：MEMS 氢气传感器完成数千万元 A 轮','领域B 能源环保','融资与量产推进','MEMS 热导氢气传感器、钯合金氢气传感器、冷媒传感器','苏州芯镁信电子科技有限公司','完成数千万元 A 轮融资（武创华工基金领投）；氢气传感器模组已通过多家电池厂与整车企业测试认证，正推进规模化量产','来源声称待核验','融资已完成；量产为「正稳步推进」，非已完成','未披露第三方现场验收或量产交付数据','C','["认证≠量产（测试认证不能写成规模化交付）", "C 级最高支持 T2，须标「来源声称」"]','「通过测试认证」未给认证名称/编号/型号；「规模化量产」为进行时表述','https://m.pedaily.cn/news/554294','目前公司基于锂电池热失控预警开发的氢气传感器模组，已通过多家知名电池制造商和新能源整车企业的测试认证，并正稳步推进规模化量产进程。','本轮所融资金将主要用于加强供应链建设、提升规模化生产制造能力','2025-08-29','2026-10-29','full','部分核（仅著录）','媒体转述企业说法，属宣传口径。用于演示「把测试认证当量产」的典型写法，以及 C 级封顶。','2026-10-29-全网检索','2026-10-29T02:06:12') on conflict (case_id) do nothing;
insert into cases_extra (case_id,title,domain,kind,tech,institution,claimed,claimed_wording,outcome,gate,evidence_level,maps_to,blocking,source_url,quote,quote2,published_at,retrieved_at,access_status,verification_status,note,batch,created_at) values ('X-03','上海市 2025 年可燃气体探测器质量监督抽查','领域A 气体传感','监管抽查','工业及商业用途点型/便携式可燃气体探测器','上海市市场监督管理局','抽查 30 批次，1 批次不合格，不合格检出率 3%；依据 GB 15322.1-2019、GB 15322.3-2019 检验报警动作值、响应时间、报警重复性、低温/恒定湿热运行、高速气流等项目','已完成','1 批次不合格（具体型号见原文附表）','政府监督抽查（法定检验）','B','["第 6 维强制准入/标准符合性是可核查的，与论文专利无关", "「买检定证书」与「法定强制」要分开"]','抽查对象为在售产品，未关联具体技术来源，不能反推任何单一项目的成熟度','http://scjgj.sh.gov.cn/1071/20260226/2c984a729c0e74d3019c9953cee455f1.html','本次抽查了30批次产品，经检验，1批次不合格，不合格检出率为3%。','本次监督抽查依据GB 15322.1-2019 《可燃气体探测器 第1部分：工业及商业用途点型可燃气体探测器》、GB 15322.3-2019《可燃气体探测器 第3部分：工业及商业用途便携式可燃气体探测器》等标准要求','2026-02-26','2026-10-29','full','人工已核对原文','政府原文。用于说明「合规是可被抽查的既成事实」，以及「抽查不合格≠项目失败」的边界。','2026-10-29-全网检索','2026-10-29T02:06:12') on conflict (case_id) do nothing;
insert into cases_extra (case_id,title,domain,kind,tech,institution,claimed,claimed_wording,outcome,gate,evidence_level,maps_to,blocking,source_url,quote,quote2,published_at,retrieved_at,access_status,verification_status,note,batch,created_at) values ('X-04','山东省 2025 年可燃气体探测器省级监督抽查','领域A 气体传感','监管抽查','家用可燃气体探测器（GB 15322.2-2019）','山东省市场监督管理局','抽查 23 批次（生产 19、网售 4），3 批次不符合标准；不合格项目为报警动作值、方位、高温（运行）试验、跌落试验；2 家生产者与 1 家销售者涉事，复检维持初检结论','已完成','3 批次不合格，复检维持初检结论','政府监督抽查（法定检验，含复检程序）','B','["第 6 维①层（强制标准符合性）", "「复检维持」说明异议程序不改变结论"]','未给出不合格产品的具体证书状态，不能据此判断其是否取得型式批准','http://amr.shandong.gov.cn/art/2025/10/27/art_76502_10314915.html','本次抽查发现 山东众海智能科技有限公司、威海市乐家电子 科技有限公司等 2家生产者生产的2批次产品，以及山东辰威电子科技有限公司1家销售者销售的1批次产品， 不符合相关标准的要求','对检验结果提出异议，并申请复检；经复检 后 ，维持初检结论。','2025-10-27','2026-10-29','full','人工已核对原文','摘录保留了原文 HTML 标签造成的多余空格；引用时按原样，不做润色。','2026-10-29-全网检索','2026-10-29T02:06:12') on conflict (case_id) do nothing;
insert into cases_extra (case_id,title,domain,kind,tech,institution,claimed,claimed_wording,outcome,gate,evidence_level,maps_to,blocking,source_url,quote,quote2,published_at,retrieved_at,access_status,verification_status,note,batch,created_at) values ('X-05','煜邦电力：终止部分募投子项目并把其余项目延期至 2026 年 12 月','跨校对照','计划终止与延期','智能巡检（含传感与数据处理、激光雷达产线、在线监测装置产线）','北京煜邦电力技术股份有限公司（688597.SH）','董事会/监事会审议通过终止部分募投子项目、其余延期至 2026 年 12 月；终止项含「传感与数据处理专项技术研究」等','已完成','部分子项目终止，其余延期','上市公司董事会/监事会决议与公告（巨潮资讯网原文）','B','["D 级计划不得当已完成；计划延期/终止是常态", "时长异常检测：募投项目从承诺到延期跨年"]','公告只说「终止/延期」与资金节余，不披露这些子项目对应的技术验证进度；不能据此推断其技术水平','http://static.cninfo.com.cn/finalpage/2025-06-26/1223981895.PDF','此次终止的巡检类的子项目包括，北京技术研发中心暨总部建设项目中的巡检机器人产品研发、陆上光伏风电巡检和海上风机巡检系统开发中的海上风机巡检系统开发、传感与数据处理专项技术研究等子项目，海盐试验测试中心技术改进项目中的智能巡检产品试验测试能力建设子项目，海盐智能巡检装备与新一代智能电力产品生产建设项目中的激光雷达生产线建设、输电线路图像在线监测装置生产线建设子项目。','公司于2025 年6 月25 日召开了第四届董事会第八次会议、第四届监事会第七次会议，审议通过了《关于终止实施募投项目部分子项目、募投项目延期及增加实施主体与实施地点的议案》。','2025-06-26','2026-10-29','full','人工已核对原文','2026-10-29 已回源：从巨潮资讯网取得公司公告原文 PDF（11 页，8745 字），摘录为原文逐字片段；此前仅见媒体转述（格隆汇），故由「部分核」升为「已核对原文」，证据级由 C 升 B。节余募集资金 9,782.73 万元亦见原文。','2026-10-29-全网检索','2026-10-29T02:06:12') on conflict (case_id) do nothing;
insert into cases_extra (case_id,title,domain,kind,tech,institution,claimed,claimed_wording,outcome,gate,evidence_level,maps_to,blocking,source_url,quote,quote2,published_at,retrieved_at,access_status,verification_status,note,batch,created_at) values ('X-06','东华大学国家大学科技园概念验证成果转化中心（松江）','跨校对照','概念验证机制','高校早期成果的概念验证与熟化（含《水溶液型耐高温上浆剂》等 10 个项目）','松江经开区管委会 ＋ 东华大学国家大学科技园','区校共建，经开区提供逾 3000 平方米空间，设概念验证基金，每年公开征集、初评路演后资助；已被认定为松江区概念验证中心（试点）；10 个项目入驻验证','已完成','中心运行中，10 个项目入驻','区级认定（试点）＋中心自身遴选流程','B','["概念验证阶段的典型材料与流程（征集—初评—路演—资助）", "「入驻验证」≠「验证通过」"]','未披露单个项目的验证结论与淘汰率；「10 个项目入驻」是过程量不是结果量','http://m.chinadevelopment.com.cn/?s=index/article/id/1975197/url/http://g60.chinadevelopment.com.cn/sjxw/2025/1226/1975197.shtml','中心由松江经开区管委会与东华大学国家大学科技园共建，经开区提供逾3000平方米物理空间','目前，东华大学已有10个项目入驻中心开展项目验证。','2025-12-26','2026-10-29','full','人工已核对原文','日期取自 URL 路径（2025/1226），页面正文未显示发布日期，故 published_at 标注为「按 URL」。','2026-10-29-全网检索','2026-10-29T02:06:12') on conflict (case_id) do nothing;
insert into cases_extra (case_id,title,domain,kind,tech,institution,claimed,claimed_wording,outcome,gate,evidence_level,maps_to,blocking,source_url,quote,quote2,published_at,retrieved_at,access_status,verification_status,note,batch,created_at) values ('X-07','清华合肥院激光气体传感成果入选安徽省首台套名单','领域A 气体传感','高校成果转化','天然气/瓦斯可燃气体探测激光芯片、激光器及系列传感器','清华大学合肥公共安全研究院 → 合肥清芯传感科技有限公司','2025-07-23 安徽省工信厅公布 2025 年度第一批首台套重大技术装备名单，该成果入选并获评「国际先进」，为全省 10 项之一；2025-03 中国光学学会科技成果评价：整体国际先进、两项技术国际领先','已完成','入选省级首台套名单（认定类，不是销售或运行证据）','省工信厅名单 ＋ 学会科技成果评价','B','["成果评价与首台套认定属 B 级，但**不等于**现场验收", "高校成果→企业主体的转化路径"]','未披露装机量、验收组织方与连续运行时长；认定类证据不能替代 T3/T4 的现场凭据','https://tsinghua-hf.edu.cn/display/?id=1034','2025年7月23日，安徽省工业和信息化厅公布2025年度第一批安徽省首台套重大技术装备名单，清华合肥院科技成果转化单位合肥清芯传感科技有限公司申报的《天然气和瓦斯可燃气体探测激光芯片、激光器及系列传感器》成功入选，并获评“国际先进”等级','2025年3月，中国光学学会组织专家对清华合肥院《天然气/瓦斯可燃气体探测激光传感关键技术、器件及应用》项目进行科技成果评价。评审结果显示，该成果整体技术水平处于国际先进','2025-07-25','2026-10-29','full','人工已核对原文','最典型的一条「认定≠运行」样本：B 级、有官方名单，但仍不足以支撑 T3。','2026-10-29-全网检索','2026-10-29T02:06:12') on conflict (case_id) do nothing;
insert into guides (topic,ord,title,question,summary,typical_evidence,pitfalls,next_steps,case_ids,anchors) values ('concept',0,'概念验证（PoC）','核心假设是什么？用什么最小实验证伪它？','概念验证要回答的是「这个原理在目标体系里是否成立」，不是「技术是否可行到能卖」。它通常只产出一份带条件的实验结论，不产出可交付物。','["明确的科学假设与可证伪的判据（例如某气体在某浓度区间的响应是否可分辨）", "最小实验装置与实验条件（温度、湿度、干扰气体、标气浓度）", "实验记录：原始数据、重复次数、失败条件的记录", "与现有方法的对比基线（否则无法判断「有响应」是否等于「有改进」）"]','["把「提出方案＋申请专利」当作概念验证完成——专利只证明新颖性，不证明原理在真实体系里成立", "只有最好的那一次数据，没有重复性与失败条件记录", "用单一浓度点的响应曲线代替全量程标定"]','["写出可证伪的判据，并预先声明什么结果算失败", "补齐干扰气体与温湿度条件下的对照实验", "把实验记录整理成可被第三方复现的形式（条件、步骤、原始数据）"]','["A03"]','["T/CASTEM 1016—2025（技术成熟度评价规范，项目锁定锚点）"]') on conflict (topic) do nothing;
insert into guides (topic,ord,title,question,summary,typical_evidence,pitfalls,next_steps,case_ids,anchors) values ('lab',1,'实验室验证','对象、条件、指标、结果和重复性如何记录？','实验室验证的门槛不是「做出来」，而是「说清楚在什么条件下、对什么对象、得到什么指标、重复几次」。没有条件的指标无法比较，也无法迁移到现场。','["被测对象与版本（型号、批次、敏感材料配方）", "实验条件与装置（标气来源、流量、温湿度、老化时长）", "指标定义与测试方法（检出限按哪个标准、响应时间取 t90 还是 t50）", "原始数据与重复性（n 次、离散度），以及未达标的记录"]','["只给「最优值」，不给分布与重复性", "指标定义与行业标准不一致，导致与竞品不可比", "把机构自述的实验结果当成第三方检测结论（在问津里 C 级最高只支持 T2）"]','["把指标定义对齐到现行国标/行标的试验方法条款", "补一份第三方检测报告，覆盖关键指标与干扰条件", "整理「未达标项清单」，它比达标项更能说明成熟度"]','["A03", "LJQ-C4"]','["GB/T 44731—2024《科技成果评估规范》（术语）"]') on conflict (topic) do nothing;
insert into guides (topic,ord,title,question,summary,typical_evidence,pitfalls,next_steps,case_ids,anchors) values ('prototype',2,'原型／相关环境验证','原型与目标环境有什么对应关系？需要哪些现场证据？','相关环境验证的关键是「像不像现场」：温度、振动、粉尘、电磁干扰、气路污染、维护可达性。原型在实验室通过、在现场漂移，是这一阶段最常见的失败模式。','["原型与目标型号的差异说明（哪些部件还是实验室件）", "相关环境与真实环境的对照表（差异项及其影响）", "环境试验记录（高低温、湿热、振动、EMC）", "现场连续运行记录：起止时间、无人值守时长、维护次数"]','["把「在合作单位车间放了两周」写成「现场验证通过」，但没有连续运行时长与验收主体", "原型与拟销售型号不是同一版本，却用原型数据支撑产品结论", "忽略防爆、防护等级等准入前置条件（这类要求论文与专利里 100% 不体现）"]','["出一份「原型—目标型号差异清单」，逐项标注验证状态", "补环境试验报告，或明确声明未做", "确定验收组织方与连续运行时长（时长本身是证据）"]','["A03", "LJQ-C1"]','["GB 15322.1-2019（可燃气体探测器）", "GB/T 3836 系列（爆炸性环境）"]') on conflict (topic) do nothing;
insert into guides (topic,ord,title,question,summary,typical_evidence,pitfalls,next_steps,case_ids,anchors) values ('pilot',3,'中试／工程化','工艺、可靠性、制造、交付和持续运行还要核实什么？','中试解决的是「放大之后还成不成立」，工程化解决的是「能不能稳定交付」。这一阶段最有说服力的证据是第三方现场验收与连续运行记录，而不是又一篇论文。','["中试规模与放大倍数，以及放大后指标的变化", "连续运行记录（小时数、开停车次数、故障与处置）", "工艺文件与良率数据、关键件供应与交付能力", "第三方现场验收意见（组织方、日期、结论、整改项）"]','["把「中试线建成」当成「中试完成」", "用一次演示代替连续运行考核", "声称一年内从实验室到挂网运行——问津已回源的 11 个成功案例，T2→T4 经验时长为 3–15 年，此类声称按纪律标红并要求补验收文件"]','["定义中试成功判据（指标、时长、良率），并预注册", "取得第三方现场验收意见书，写明组织方与连续运行时长", "整理交付与售后方案，说明规模化后的质量一致性如何保证"]','["LJQ-C1", "LJQ-C3", "A03"]','["问津案例库：成功跃迁 11 例（05_案例库/成功跃迁案例_T2到T4.md）"]') on conflict (topic) do nothing;
insert into guides (topic,ord,title,question,summary,typical_evidence,pitfalls,next_steps,case_ids,anchors) values ('transfer',4,'转移／合作','许可、转让、合作研发、作价投资有什么区别？','四种路径转移的东西不同：许可转移使用权，转让转移权利本身，合作研发共同承担投入与风险，作价投资把权利折成股权。任何一种都不自动等于技术已部署。','["权利状态：专利登记簿副本、发明人归属、是否存在共有权人", "合同要点：标的、地域、期限、独占/非独占、里程碑与付款条件", "作价投资的评估报告与国资/学校审批文件", "排他条款与后续改进成果的归属约定"]','["把「签署战略合作协议」当成「已许可」——意向与合同是两种证据", "把合同金额当成到账收入", "忽略职务发明与共有权人同意，导致后续转让受阻"]','["先取专利登记簿副本确认权利状态与法律事件", "把意向书、框架协议、正式合同分开记录，各自标注状态", "明确后续改进成果归属，避免二次转化受阻"]','["LJQ-C1", "LJQ-F1"]','["国办发〔2023〕37号《专利转化运用专项行动方案（2023—2025年）》"]') on conflict (topic) do nothing;
insert into guides (topic,ord,title,question,summary,typical_evidence,pitfalls,next_steps,case_ids,anchors) values ('deployment',5,'实施／推广','是否有真实部署、用户使用、持续运行或复制推广证据？','实施阶段的证据必须来自使用方而不是研制方：谁在用、用了多久、替代了什么、出过什么故障。复制推广还要能说清第二个用户为什么买。','["部署清单：用户、场景、数量、安装日期、运行时长", "用户侧记录：运维工单、故障率、备件消耗", "采购合同与验收单（区分合同金额与到账收入）", "第二个及以后的客户证据（复制推广的分水岭）"]','["把「示范工程」当成「商业化」，示范往往有补贴与特殊运维支持", "只有首个客户，却宣称「已规模化应用」", "忽略强制准入与定期检定带来的持续合规成本"]','["按型号与量程整理在售产品的准入证书与检定记录", "统计真实运行时长与故障率，形成可核对的运维台账", "取得第二个独立客户的采购与验收证据"]','["A03", "LJQ-C3", "LJQ-F2"]','["市场监管总局 2020 年第 42 号公告（《实施强制管理的计量器具目录》）"]') on conflict (topic) do nothing;
